package com.intermarche.e2e.engine.fieldops;
import io.quarkus.test.junit.QuarkusTest;import io.quarkus.narayana.jta.QuarkusTransaction;import io.restassured.response.Response;import org.junit.jupiter.api.Test;
import com.intermarche.backoffice.domain.stock.*;import com.intermarche.backoffice.domain.store.*;import com.intermarche.backoffice.domain.executing.*;import com.intermarche.backoffice.domain.util.DateTimeProvider;
import java.math.BigDecimal;import java.util.*;import static io.restassured.RestAssured.given;import static org.junit.jupiter.api.Assertions.*;
@QuarkusTest @jakarta.enterprise.inject.Typed(InventoryCustodyWorkflowTest.class)
class InventoryCustodyWorkflowTest extends TraceabilityWorkflowTest {
 Response api(String actor,String method,String path,Object body){var r=given().auth().oauth2(actor).contentType("application/json");if(body!=null)r.body(body);var result=r.request(method,"/inventories"+path);if(result.statusCode()>=400)System.out.println(path+" "+result.asString());return result;}
 record Cell(Long buffer,Long cabinet,Long tote){}
 Cell cell(){return QuarkusTransaction.requiringNew().call(()->{var b=new Buffer();b.building=Building.findById(f.building());b.bufferCode="COUNT-CUSTODY";b.ambientCapacity=10;b.persist();var c=new BufferCabinet();c.buffer=b;c.code="A";c.rows=1;c.columns=1;c.zone=TemperatureZone.AMBIENT;c.persist();var tote=PickedItem.<PickedItem>findById(f.item()).loadedTote;return new Cell(b.id,c.id,tote.id);});}
 Map<String,Object> observed(Cell cell,int quantity){given().auth().oauth2(f.manager()).contentType("application/json").body(Map.of("storeId",f.store(),"toteId",cell.tote,"bufferId",cell.buffer,"cabinetId",cell.cabinet,"cellRow",1,"cellColumn",1)).post("/store-operations/buffer-deposits").then().statusCode(200);long order=api(f.manager(),"POST","",Map.of("storeId",f.store(),"buildingId",f.building(),"scopeKind","CELL","cabinetId",cell.cabinet,"cellRow",1,"cellColumn",1,"start",DateTimeProvider.now().toString(),"end",DateTimeProvider.now().plusHours(1).toString(),"requestKey",key())).then().statusCode(200).extract().jsonPath().getLong("id");long execution=command(Map.of("storeId",f.store(),"orderId",order,"action","RESERVE","requestKey",key())).then().statusCode(200).extract().jsonPath().getLong("orders[0].executions[0].id");var session=command(Map.of("storeId",f.store(),"executionId",execution,"action","START_INVENTORY","requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("inventory");for(int round=1;round<=2;round++){long line=((Number)((List<Map<String,Object>>)session.get("lines")).getFirst().get("id")).longValue();session=api(f.picker(),"POST","/counts",Map.of("storeId",f.store(),"sessionId",session.get("id"),"lineId",line,"state","COUNTED","quantity",quantity,"expectedRevision",session.get("revision"),"requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");session=api(f.picker(),"POST","/sessions/submit",Map.of("storeId",f.store(),"sessionId",session.get("id"),"expectedRevision",session.get("revision"),"requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");if(round==1)session=api(f.picker(),"POST","/sessions/recount",Map.of("storeId",f.store(),"sessionId",session.get("id"),"expectedRevision",session.get("revision"),"requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");}return session;}
 void apply(Map<String,Object> session,Integer retained){var review=api(f.manager(),"GET","/sessions/"+session.get("id")+"/review?storeId="+f.store(),null).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");var input=new LinkedHashMap<String,Object>(Map.of("storeId",f.store(),"sessionId",session.get("id"),"expectedRevision",session.get("revision"),"requestKey",key(),"reviewToken",review.get("reviewToken"),"reason","Écart physique du bac vérifié avec deux comptages"));if(retained!=null){var line=((List<Map<String,Object>>)review.get("lines")).getFirst();var allocation=((List<Map<String,Object>>)line.get("allocations")).getFirst();input.put("retainedAllocations",Map.of(allocation.get("id").toString(),retained));}var approved=api(f.manager(),"POST","/sessions/approve",input).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");var body=Map.of("storeId",f.store(),"sessionId",approved.get("id"),"expectedRevision",approved.get("revision"),"requestKey",key());api(f.manager(),"POST","/sessions/apply",body).then().statusCode(200);api(f.manager(),"POST","/sessions/apply",body).then().statusCode(200);}
 @Test void aCountedShortageReducesTheActualAllocationAndCreatesARecoverablePickingShortage(){line();var stock=stock();pick(stock);var cell=cell();var session=observed(cell,1);apply(session,1);QuarkusTransaction.requiringNew().run(()->{var item=PickedItem.<PickedItem>findById(f.item());eq(1,item.quantity);var allocation=PickedStockAllocation.<PickedStockAllocation>find("state.itemId=?1 and quantity>0",f.item()).firstResult();eq(1,allocation.quantity);eq(1,com.intermarche.backoffice.engine.stock.StockSegments.balance(allocation.holding,DateTimeProvider.now()));eq(19,stocks.availability(stock.account(),null,DateTimeProvider.now()).physical);assertEquals(1,PickingShortage.count("lotLine",item.lotLine));eq(1,PickingShortage.<PickingShortage>find("lotLine",item.lotLine).firstResult().quantity);});var execution=given().auth().oauth2(f.picker()).get("/handling-orders/operator/executions/"+f.execution()+"?storeId="+f.store()).then().statusCode(200).extract().jsonPath();var events=execution.<Map<String,Object>>getList("resolutions");assertEquals(1,events.size());assertEquals(true,events.getFirst().get("canCorrect"));var correction=command("CORRECT_SHORTAGE");correction.putAll(Map.of("orderId",f.order(),"shortageId",((Number)events.getFirst().get("id")).longValue(),"quantity",1,"expectedQuantity",1,"reason","Reprendre le prélèvement après l’écart d’inventaire"));command(correction).then().statusCode(200);QuarkusTransaction.requiringNew().run(()->{assertEquals(1,PickedItem.count("lotLine.id=(select p.lotLine.id from PickedItem p where p.id=?1) and status=?2 and quantity=1",f.item(),PickedItem.PickStatus.PENDING));eq(19,stocks.availability(stock.account(),null,DateTimeProvider.now()).physical);});}
 @Test void additionalGoodsRemainLooseRatherThanBeingSilentlyAssignedToTheCustomer(){line();var stock=stock();pick(stock);var cell=cell();apply(observed(cell,3),null);QuarkusTransaction.requiringNew().run(()->{var item=PickedItem.<PickedItem>findById(f.item());eq(2,item.quantity);var allocation=PickedStockAllocation.<PickedStockAllocation>find("state.itemId=?1 and quantity>0",f.item()).firstResult();eq(2,allocation.quantity);eq(2,com.intermarche.backoffice.engine.stock.StockSegments.balance(allocation.holding,DateTimeProvider.now()));eq(21,stocks.availability(stock.account(),null,DateTimeProvider.now()).physical);var loose=BufferToteStockLocation.<BufferToteStockLocation>find("loadedTote",item.loadedTote).firstResult();assertNotNull(loose);eq(1,StockMovement.getEntityManager().createQuery("select sum(m.quantity) from StockMovement m where m.location=?1",BigDecimal.class).setParameter(1,loose).getSingleResult());});}
}
